tokenRequests.description:
tokenRequests indicates the CSI driver needs pods' service account tokens it is mounting volume for to do necessary authentication. Kubelet will pass the tokens in VolumeContext in the CSI NodePublishVolume calls. The CSI driver should parse and validate the following VolumeContext: "csi.storage.k8s.io/serviceAccount.tokens": {
  "<audience>": {
    "token": <token>,
    "expirationTimestamp": <expiration timestamp in RFC3339>,
  },
  ...
}

Note: Audience in each TokenRequest should be different and at most one token is empty string. To receive a new token after expiry, RequiresRepublish can be used to trigger NodePublishVolume periodically.

samples.content:
targetScope = 'local'

@secure()
@description('The contents of a kubeconfig file, base-64 encoded.')
param kubeConfig string

@description('The namespace to deploy into. It must already exist.')
param namespace string = 'default'

@description('The number of echo server replicas to run.')
param replicas int = 1

extension kubernetes with {
  kubeConfig: kubeConfig
  namespace: namespace
}

var name = 'echo-server'
var image = 'ealen/echo-server:0.8.12'
var containerPort = 80
var servicePort = 8080

var labels = {
  app: name
}

@description('Echo server deployment')
resource deployment 'apps/Deployment@v1' = {
  metadata: {
    name: name
    labels: labels
  }
  spec: {
    replicas: replicas
    selector: {
      matchLabels: labels
    }
    template: {
      metadata: {
        name: name
        labels: labels
      }
      spec: {
        containers: [
          {
            name: name
            image: image
            ports: [
              {
                name: 'http'
                containerPort: containerPort
              }
            ]
            resources: {
              requests: {
                cpu: '50m'
                memory: '64Mi'
              }
              limits: {
                cpu: '200m'
                memory: '128Mi'
              }
            }
            readinessProbe: {
              httpGet: {
                path: '/'
                // 'port' is a Kubernetes IntOrString, which the type definitions model as a string, so
                // the named container port is referenced rather than its number.
                port: 'http'
              }
              initialDelaySeconds: 2
              periodSeconds: 5
            }
          }
        ]
      }
    }
  }
}

@description('Echo server service')
resource service 'core/Service@v1' = {
  metadata: {
    name: name
    labels: labels
  }
  spec: {
    type: 'ClusterIP'
    selector: labels
    ports: [
      {
        port: servicePort
        targetPort: 'http'
      }
    ]
  }
}

output deploymentName string = deployment.metadata.name
output serviceName string = service.metadata.name

targetScope = 'local'

@secure()
@description('The contents of a kubeconfig file, base-64 encoded.')
param kubeConfig string

@description('The namespace to deploy into. It must already exist.')
param namespace string = 'default'

@description('The service type to expose the front end with. Use \'LoadBalancer\' on a cloud cluster.')
@allowed([
  'ClusterIP'
  'LoadBalancer'
  'NodePort'
])
param frontEndServiceType string = 'LoadBalancer'

extension kubernetes with {
  kubeConfig: kubeConfig
  namespace: namespace
}

var backName = 'azure-vote-back'
var backPort = 6379

var frontName = 'azure-vote-front'
var frontPort = 80

@description('Application back-end deployment (redis)')
resource backDeploy 'apps/Deployment@v1' = {
  metadata: {
    name: backName
  }
  spec: {
    replicas: 1
    selector: {
      matchLabels: {
        app: backName
      }
    }
    template: {
      metadata: {
        name: backName
        labels: {
          app: backName
        }
      }
      spec: {
        containers: [
          {
            name: backName
            image: 'redis:7'
            env: [
              {
                name: 'ALLOW_EMPTY_PASSWORD'
                value: 'yes'
              }
            ]
            resources: {
              requests: {
                cpu: '100m'
                memory: '128Mi'
              }
              limits: {
                cpu: '250m'
                memory: '256Mi'
              }
            }
            ports: [
              {
                containerPort: backPort
                name: 'redis'
              }
            ]
          }
        ]
      }
    }
  }
}

@description('Configure back-end service')
resource backSvc 'core/Service@v1' = {
  metadata: {
    name: backName
  }
  spec: {
    ports: [
      {
        port: backPort
      }
    ]
    selector: {
      app: backName
    }
  }
}

@description('Application front-end deployment (website)')
resource frontDeploy 'apps/Deployment@v1' = {
  metadata: {
    name: frontName
  }
  spec: {
    replicas: 1
    selector: {
      matchLabels: {
        app: frontName
      }
    }
    template: {
      metadata: {
        name: frontName
        labels: {
          app: frontName
        }
      }
      spec: {
        nodeSelector: {
          'kubernetes.io/os': 'linux'
        }
        containers: [
          {
            name: frontName
            image: 'neilpeterson/azure-vote-front:v3'
            resources: {
              requests: {
                cpu: '100m'
                memory: '128Mi'
              }
              limits: {
                cpu: '250m'
                memory: '256Mi'
              }
            }
            ports: [
              {
                containerPort: frontPort
              }
            ]
            env: [
              {
                name: 'REDIS'
                value: backName
              }
            ]
          }
        ]
      }
    }
  }
}

@description('Configure front-end service')
resource frontSvc 'core/Service@v1' = {
  metadata: {
    name: frontName
  }
  spec: {
    type: frontEndServiceType
    ports: [
      {
        port: frontPort
      }
    ]
    selector: {
      app: frontName
    }
  }
}

output frontEndServiceName string = frontSvc.metadata.name
